'use strict';

const { User } = require('../../database');

async function findAll() {
  return User.findAll({ order: [['createdAt', 'DESC']] });
}

async function findById(id) {
  return User.findByPk(id);
}

/**
 * Find an existing user by UUID, or create a new anonymous placeholder row.
 * Used by the extension where there is no registration flow — the client
 * generates a stable UUID and we ensure a corresponding DB row exists.
 *
 * @param {string} id  - UUID v4 generated by the browser extension.
 * @returns {Promise<import('sequelize').Model>}
 */
async function findOrCreateById(id) {
  const [user] = await User.findOrCreate({
    where: { id },
    defaults: {
      id,
      // Sentinel email keeps the NOT-NULL + unique constraint satisfied
      // without requiring a real sign-up flow.
      email: `anon-${id}@extension.local`,
      name: 'Extension User',
    },
  });
  return user;
}

async function create(data) {
  return User.create(data);
}

async function update(id, data) {
  const user = await User.findByPk(id);
  if (!user) return null;
  return user.update(data);
}

async function remove(id) {
  const user = await User.findByPk(id);
  if (!user) return null;
  await user.destroy();
}

module.exports = { findAll, findById, findOrCreateById, create, update, remove };
